<script lang="ts" module>import type { RxColor } from '$lib/registry/lib/color'; export interface DotStepperProps { current?:number; count:number; color?:RxColor; variant?:'default'|'bars'|'elastic'|'glow'|'ring'|'worm'; labels?:string[]; disabled?:boolean; onCurrentChange?:(index:number)=>void; }</script>
<script lang="ts">import { styleColor } from '$lib/registry/lib/color'; let {current=$bindable(0),count,color,variant='default',labels=[],disabled=false,onCurrentChange}:DotStepperProps=$props(); const safeCount=$derived(Math.max(0,Math.floor(count))); function select(i:number){if(disabled)return;current=i;onCurrentChange?.(i);}</script>
<nav class="rx-dots rx-dots--{variant}" aria-label="Progress" style={styleColor(color) ?? '--rx-color: var(--rx-primary)'}><div class="rx-dots__track" style={`--rx-current:${current};--rx-count:${safeCount}`}>
 {#if variant==='worm' && safeCount>0}<span class="rx-dots__worm" aria-hidden="true"></span>{/if}
 {#each Array(safeCount) as _,i}<button type="button" aria-label={labels[i] ?? `Go to step ${i+1}`} aria-current={i===current?'step':undefined} disabled={disabled} class:active={i===current} onclick={()=>select(i)}><span aria-hidden="true"></span>{#if labels[i]}<small>{labels[i]}</small>{/if}</button>{/each}
</div></nav>
<style>.rx-dots__track{position:relative;display:flex;align-items:flex-start;gap:.65rem}.rx-dots button{display:grid;justify-items:center;gap:.4rem;border:0;background:transparent;color:rgb(var(--rx-text));padding:.25rem;cursor:pointer}.rx-dots button>span{width:.7rem;height:.7rem;border-radius:999px;background:rgb(var(--rx-muted)/.35);transition:transform .3s var(--rx-ease),background .3s}.rx-dots button.active>span{background:rgb(var(--rx-color));transform:scale(1.35)}.rx-dots small{font-size:.72rem}.rx-dots--bars button>span{width:2rem;border-radius:.3rem}.rx-dots--ring button.active>span{background:transparent;box-shadow:inset 0 0 0 3px rgb(var(--rx-color))}.rx-dots--glow button.active>span{box-shadow:0 0 1rem rgb(var(--rx-color)/.8)}.rx-dots--elastic button.active>span{transform:scaleX(2)}.rx-dots__worm{position:absolute;left:.25rem;top:.25rem;width:.7rem;height:.7rem;border-radius:999px;background:rgb(var(--rx-color));transform:translateX(calc(var(--rx-current) * 1.85rem));transition:transform .35s var(--rx-ease);z-index:1}.rx-dots--worm button>span{opacity:.3}.rx-dots button:focus-visible{outline:2px solid rgb(var(--rx-color));outline-offset:2px}@media(prefers-reduced-motion:reduce){.rx-dots button>span,.rx-dots__worm{transition-duration:0ms}}</style>
